// HappyDOM smoke host only. This is not a CSS loader for applications or browsers.
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const TOKEN_PREFIX =
  '/* This file is auto-generated by @proto.ui/cli (proto-ui tokens). */\n' +
  '/* Do not edit by hand. */\n\n@layer proto-ui {';
const ENTRY =
  '/* This file is auto-generated by @proto.ui/cli. */\n' +
  '/* Do not edit by hand. */\n' +
  '/* Hosts with named reset or consumer layers must declare their full order before this entry loads. */\n\n' +
  '@layer theme, proto-ui;\n\n' +
  "@import './shadcn-theme.css' layer(theme);\n" +
  "@import './proto-ui-tokens.generated.css';\n";
const FILES = ['proto-ui-style.css', 'shadcn-theme.css', 'proto-ui-tokens.generated.css'];
// Exact canonical CLI output only. HappyDOM cannot model cascade layers; the
// original bytes remain the browser/build source and are hashed in evidence.
const THEME_SELECTION_BODY = `::selection {
      background-color: var(--pui-selection);
      color: var(--pui-selection-foreground);
    }`;
const THEME_SELECTION_LAYER = `@layer theme {
    ${THEME_SELECTION_BODY}
  }`;

export function unwrapGeneratedThemeSelectionLayer(css) {
  const selectionRange = assertBoundedBody(css, true);
  return selectionRange
    ? css.slice(0, selectionRange[0]) + THEME_SELECTION_BODY + css.slice(selectionRange[1])
    : css;
}

// Bounded delimiter validation, not a CSS parser: only the generator's exact
// single outer wrapper is accepted. Comments/quoted strings may contain braces.
// Nested @media, @keyframes, etc. are left byte-for-byte intact. Other @layer or
// @import forms fail closed rather than being silently removed or flattened.
export function unwrapGeneratedTokenLayer(css) {
  if (!css.startsWith(TOKEN_PREFIX) || !css.endsWith('\n}\n')) {
    throw new Error('consumer CSS smoke: expected the generated single outer @layer proto-ui');
  }
  const body = css.slice(TOKEN_PREFIX.length, -2);
  assertBoundedBody(body);
  return body;
}

function assertBoundedBody(body, allowThemeSelection = false) {
  let selectionRange = null;
  let depth = 0;
  let quote = null;
  let comment = false;
  for (let i = 0; i < body.length; i += 1) {
    const c = body[i];
    const next = body[i + 1];
    if (comment) {
      if (c === '*' && next === '/') {
        comment = false;
        i += 1;
      }
    } else if (quote) {
      if (c === '\\') i += 1;
      else if (c === quote) quote = null;
    } else if (c === '/' && next === '*') {
      comment = true;
      i += 1;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === '\\') {
      // Escaped identifiers are outside this generator's at-rule vocabulary.
      throw new Error('consumer CSS smoke: unexpected unquoted escape');
    } else if (c === '@' && /^@(layer|import)\b/i.test(body.slice(i))) {
      if (allowThemeSelection && depth === 0 && body.startsWith(THEME_SELECTION_LAYER, i)) {
        if (selectionRange) throw new Error('consumer CSS smoke: repeated theme selection layer');
        selectionRange = [i, i + THEME_SELECTION_LAYER.length];
        i = selectionRange[1] - 1;
      } else {
        throw new Error('consumer CSS smoke: additional @layer or @import is unsupported');
      }
    } else if (c === '{') {
      depth += 1;
    } else if (c === '}') {
      depth -= 1;
      if (depth < 0) throw new Error('consumer CSS smoke: unexpected outer CSS structure');
    }
  }
  if (depth !== 0 || quote || comment) {
    throw new Error('consumer CSS smoke: unbalanced generated CSS');
  }
  return selectionRange;
}

export function loadConsumerStyles(
  document,
  { root = process.cwd(), stylesDir = join(root, 'src', 'styles'), evidenceName = 'styled' } = {}
) {
  const originals = FILES.map((name) => ({
    name,
    bytes: readFileSync(join(stylesDir, name)),
  }));
  if (originals[0].bytes.toString('utf8') !== ENTRY) {
    throw new Error('consumer CSS smoke: unsupported generated entry/import order');
  }
  const theme = unwrapGeneratedThemeSelectionLayer(originals[1].bytes.toString('utf8'));
  // HappyDOM can attach an unparseable quoted bracket-token selector's
  // declarations to the preceding rule (e.g. h-[1.15rem] overwrites h-8).
  // Escape only literal brackets in the generated token attribute values:
  // this is an equivalent CSS string, not a filtered stylesheet or paint fix.
  // Original browser/build bytes above remain untouched and are hashed below.
  const tokens = unwrapGeneratedTokenLayer(originals[2].bytes.toString('utf8')).replace(
    /\[data-pui-style~="((?:\\.|[^"\\])*)"\]/g,
    (_selector, value) =>
      `[data-pui-style~="${value.replace(/\[/g, '\\[').replace(/\]/g, '\\]')}"]`
  );
  const evidenceDir = join(root, 'consumer-css-evidence', evidenceName);
  mkdirSync(evidenceDir, { recursive: true });
  const files = originals.map(({ name, bytes }) => {
    writeFileSync(join(evidenceDir, name), bytes);
    return {
      name,
      bytes: bytes.length,
      sha256: createHash('sha256').update(bytes).digest('hex'),
    };
  });
  const limitation =
    'HappyDOM only: explicit theme then token load; single outer proto-ui layer and exact canonical theme selection wrapper removed; token selector string brackets escaped equivalently. ' +
    'No cascade-layer, selection-paint, width/layout, paint, or native hit-testing equivalence is claimed. ' +
    'Browser/build entry consumes the original complete stylesheet.';
  writeFileSync(
    join(evidenceDir, 'manifest.json'),
    `${JSON.stringify({ files, limitation }, null, 2)}\n`
  );
  const styles = [theme, tokens].map((css, index) => {
    const style = document.createElement('style');
    style.dataset.consumerSmokeCss = index === 0 ? 'theme' : 'tokens';
    style.textContent = css;
    document.head.appendChild(style);
    return style;
  });
  console.log(
    `consumer CSS smoke: ${evidenceName}; originals + SHA-256 at ${evidenceDir}. ${limitation}`
  );
  return { styles, files, evidenceDir };
}

// Independent direct Button Rhea consumer oracle: shadcn-ui/ui
// 25af02b1b467fcd53b63e0c6d6d324c57c16ef18, apps/v4/registry/styles/style-rhea.css.
// Compound command paint has a separate pin and is not changed by this oracle.
// A removed non-paint marker (group/button) is not evidence of missing styles.
export function assertDefaultButtonTokens(element, label) {
  if (!element) throw new Error(`${label}: Button host is missing`);
  const tokens = new Set((element.getAttribute('data-pui-style') ?? '').split(/\s+/));
  for (const token of [
    'inline-flex',
    'shrink-0',
    'items-center',
    'justify-center',
    'rounded-[var(--pui-radius-2xl)]',
    'text-sm',
    'font-medium',
    'bg-primary',
    'text-primary-foreground',
    'h-8',
    'gap-1.5',
    'px-3',
    'leading-5',
    'py-0',
    'border',
    'border-transparent',
    'whitespace-nowrap',
  ]) {
    if (!tokens.has(token))
      throw new Error(`${label}: Button current recipe token is missing: ${token}`);
    if (element.classList.contains(token))
      throw new Error(`${label}: Button leaked prototype token into class: ${token}`);
  }
}

// Styled consumers must also observe real CSS installation. HappyDOM computed
// values below are structural evidence, not native layout/paint or motion proof.
export function assertStyledButton(element, label) {
  assertDefaultButtonTokens(element, label);
  const view = element.ownerDocument.defaultView;
  const style = view.getComputedStyle(element);
  const rootFont =
    Number.parseFloat(view.getComputedStyle(element.ownerDocument.documentElement).fontSize) || 16;
  const expected = {
    display: 'inline-flex',
    flexShrink: '0',
    alignItems: 'center',
    justifyContent: 'center',
    boxSizing: 'border-box',
    height: `${2 * rootFont}px`,
    gap: `${0.375 * rootFont}px`,
    // HappyDOM does not reliably expand padding-inline/block into physical
    // longhands. Check the installed logical declarations; browser tests retain
    // exact physical padding checks at the fixed root font.
    paddingInline: `${0.75 * rootFont}px`,
    paddingBlock: '0px',
  };
  for (const [property, value] of Object.entries(expected)) {
    // HappyDOM retains logical padding/gap in rem; compare exact unit equivalents.
    // This is bounded computed-CSS normalization, not a layout simulation.
    const raw = style.getPropertyValue(
      property.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)
    );
    const actual = /^\d+(?:\.\d+)?rem$/.test(raw) ? `${Number.parseFloat(raw) * rootFont}px` : raw;
    if (actual !== value)
      throw new Error(
        `${label}: Button generated CSS mismatch: ${property}=${raw}, expected=${value}`
      );
  }
}

// P-SHADCN-SWITCH[-THUMB]-CURRENT-VISUAL-SURFACE: fixed New York
// 02cad611 default recipe. There is no positioned-box or staticHitInset prerequisite.
// Computed structure proves CSS installation. Exact installed declarations retain
// rem units and state travel; HappyDOM is not evidence of layout, paint or motion.
export function assertStyledSwitch(element, label) {
  if (!element) throw new Error(`${label}: Switch host is missing`);
  const view = element.ownerDocument.defaultView;
  const style = view.getComputedStyle(element);
  const structural = {
    display: 'inline-flex',
    flexShrink: '0',
    alignItems: 'center',
    boxSizing: 'border-box',
    borderWidth: '1px',
    borderRadius: '9999px',
    padding: '0px',
  };
  for (const [property, expected] of Object.entries(structural)) {
    if (style[property] !== expected) {
      throw new Error(
        `${label}: generated Switch structural CSS not applied: ${property}=${style[property]}, expected=${expected}`
      );
    }
  }
  const thumb = element.firstElementChild;
  if (!thumb) throw new Error(`${label}: Switch Thumb is missing`);
  const thumbStyle = view.getComputedStyle(thumb);
  if (thumbStyle.display !== 'block' || thumbStyle.pointerEvents !== 'none') {
    throw new Error(`${label}: generated Switch Thumb structural CSS not applied`);
  }
  const generatedStyles = [
    ...element.ownerDocument.querySelectorAll('style[data-consumer-smoke-css="tokens"]'),
  ]
    .map((sheet) => sheet.textContent)
    .join('\n');
  const requireRule = (host, token, declarations, suffix = '') => {
    if (host && !host.getAttribute('data-pui-style')?.split(/\s+/).includes(token)) {
      throw new Error(`${label}: Switch current recipe token is missing: ${token}`);
    }
    // Match the exact bounded generator rule, not a CSSOM-normalized px result.
    // HappyDOM does not reliably resolve arbitrary-value selectors or transforms.
    const selector = `:where([data-pui-style~="${token}"])${suffix}`;
    // Parse with the host's CSSOM, not a handwritten declaration/cascade parser.
    // HappyDOM 15 cannot parse some arbitrary-value selectors. Substitute only
    // this exact selector in a detached parsing copy; the installed CSS and DOM
    // are untouched. Comments and inactive/nested rules retain their meaning.
    const marker = '[data-consumer-smoke-rule="target"]';
    if (generatedStyles.includes(marker)) throw new Error(`${label}: reserved CSS smoke selector`);
    const parsed = new view.CSSStyleSheet();
    parsed.replaceSync(generatedStyles.replaceAll(selector, marker));
    const matches = [];
    const visit = (rules, depth = 0) => {
      for (const rule of rules) {
        if (rule.selectorText === marker) matches.push({ rule, depth });
        if (rule.cssRules) visit(rule.cssRules, depth + 1);
      }
    };
    visit(parsed.cssRules);
    if (matches.length !== 1 || matches[0].depth !== 0) {
      throw new Error(`${label}: Switch generated CSS rule is missing or duplicated: ${token}`);
    }
    const expected = new view.CSSStyleSheet();
    expected.replaceSync(`${marker} { ${declarations.join('; ')}; }`);
    // Accept only this generator's canonical declaration set. CSSOM resolves
    // declaration priority; unexpected property casing, priorities and extra
    // declarations fail closed rather than emulating a general cascade here.
    if (matches[0].rule.style.cssText !== expected.cssRules[0].style.cssText) {
      throw new Error(
        `${label}: Switch generated CSS declaration is missing or noncanonical: ${token}`
      );
    }
  };
  requireRule(element, 'h-[1.15rem]', ['height: 1.15rem']);
  requireRule(element, 'w-8', ['width: 2rem']);
  requireRule(element, 'shadow-xs', [
    '--pui-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05)',
    'box-shadow: var(--pui-ring-offset-shadow, 0 0 #0000), var(--pui-ring-shadow, 0 0 #0000), var(--pui-shadow, 0 0 #0000)',
  ]);
  requireRule(thumb, 'size-4', ['width: 1rem', 'height: 1rem']);
  const transform =
    'transform: translate(var(--pui-translate-x, 0), var(--pui-translate-y, 0)) scale(var(--pui-scale-x, 1), var(--pui-scale-y, 1))';
  requireRule(null, 'translate-x-0', ['--pui-translate-x: 0px', transform]);
  requireRule(null, 'translate-x-[calc(100%_-_2px)]', [
    '--pui-translate-x: calc(100% - 2px)',
    transform,
  ]);
  requireRule(
    null,
    'data-[checked]:not-[data-draggable]:translate-x-[calc(100%_-_2px)]',
    ['--pui-translate-x: calc(100% - 2px)', transform],
    '[data-checked]:not([data-draggable])'
  );
  assertSwitchThumbState(element, element.getAttribute('aria-checked') === 'true', label);
  // These simple rem properties are resolved by this host. This is computed CSS,
  // not measured layout. Arbitrary height/transform selectors need browser QA.
  const rootFont =
    Number.parseFloat(view.getComputedStyle(element.ownerDocument.documentElement).fontSize) || 16;
  for (const [part, actual, expected] of [
    ['Root width', style.width, `${2 * rootFont}px`],
    ['Thumb width', thumbStyle.width, `${rootFont}px`],
    ['Thumb height', thumbStyle.height, `${rootFont}px`],
    [
      'Root shadow variable',
      style.getPropertyValue('--pui-shadow'),
      '0 1px 2px 0 rgb(0 0 0 / 0.05)',
    ],
  ]) {
    if (actual !== expected) {
      throw new Error(
        `${label}: Switch computed CSS mismatch: ${part}=${actual}, expected=${expected}`
      );
    }
  }
}

// C-FEEDBACK-RESIDENT-MOTION-0001-A/F: relevant Rules stay in the runtime.
// With no delivered reference-box measurement, checked percentage travel must
// retain its active semantic token. Zero travel needs no measurement, so the
// resident sink may instead own exactly the inline 0px endpoint. This is a
// layoutless smoke assertion, not a native motion or measured-travel oracle.
export function assertSwitchThumbState(element, expectedChecked, label) {
  const thumb = element?.firstElementChild;
  const checked = element?.getAttribute('aria-checked');
  const rootChecked = element?.hasAttribute('data-checked');
  const thumbChecked = thumb?.hasAttribute('data-checked');
  const tokens = thumb?.getAttribute('data-pui-style')?.split(/\s+/) ?? [];
  const inline = thumb?.style?.getPropertyValue('translate') ?? '';
  const priority = thumb?.style?.getPropertyPriority('translate') ?? '';
  const transform = thumb?.style?.getPropertyValue('transform') ?? '';
  const inlineVariables = [
    '--pui-translate-x',
    '--pui-translate-y',
    '--pui-scale-x',
    '--pui-scale-y',
  ]
    .map((property) => [property, thumb?.style?.getPropertyValue(property) ?? ''])
    .filter(([, value]) => value !== '');
  const detail = JSON.stringify({
    checked,
    rootChecked,
    thumbChecked,
    tokens,
    inline,
    priority,
    transform,
    inlineVariables,
  });
  if (
    !thumb ||
    checked !== String(expectedChecked) ||
    rootChecked !== expectedChecked ||
    thumbChecked !== expectedChecked
  ) {
    throw new Error(`${label}: Switch Root/Thumb checked state mismatch: ${detail}`);
  }
  const ownedTokens = tokens.filter((token) => /^-?translate-[xy]-/.test(token));
  const selectorTarget = tokens.some((token) => /:-?translate-[xy]-/.test(token));
  const expectedToken = expectedChecked ? 'translate-x-[calc(100%_-_2px)]' : 'translate-x-0';
  const runtimeToken =
    ownedTokens.length === 1 && ownedTokens[0] === expectedToken && inline === '';
  // CSSOM may serialize the zero Y coordinate implicitly; both are exactly zero.
  const inlineZero =
    !expectedChecked && ownedTokens.length === 0 && (inline === '0px 0px' || inline === '0px');
  if (
    selectorTarget ||
    inlineVariables.length > 0 ||
    priority !== '' ||
    transform !== '' ||
    (!runtimeToken && !inlineZero)
  ) {
    throw new Error(
      `${label}: Switch Thumb effective translate endpoint is missing or conflicting: ${detail}`
    );
  }
  console.log(
    `consumer Switch Thumb: ${label}; ${JSON.stringify({
      checked,
      rootChecked,
      thumbChecked,
      channel: runtimeToken ? 'token' : 'inline',
      translateTokens: ownedTokens,
      inline,
      priority,
    })}`
  );
}
